def phones_to_list(apps, schema_editor):
    """D40: the Phone section is a list. Each saved profile phone becomes the
    first entry of that list (the profile keeps its copy, so nothing is lost)."""
    ContactProfile = apps.get_model("community", "ContactProfile")
    ContactMethod = apps.get_model("community", "ContactMethod")
    for profile in ContactProfile.objects.exclude(phone=""):
        value = profile.phone.strip()
        if not value:
            continue
        if ContactMethod.objects.filter(person_id=profile.person_id, kind="phone").exists():
            continue
        ContactMethod.objects.create(person_id=profile.person_id, kind="phone", value=value)


